% 15 & $0.258$ & not enough statistical evidence to reject $H0$ \\
% \hline
% 30 & $0.022$ & there is statistical evidence to reject $H0$ \\
% \hline
% 60 & $0.038$ & there is statistical evidence to reject $H0$ \\
% \hline
% \end{tabular}
